// Step 2 of the manual pipeline: fetch ONE manual/spec PDF by URL, egressing
// through this box's VPN (NOT the sandbox/home IP). Returns the bytes base64 when
// the URL is a real PDF; flags HTML/portal pages so the orchestrator can route them
// to the headless-browser path (step 2b). Mirrors the rover-expand fetch pattern.
const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
const helpers = this.helpers;
const payload = $json && $json.body ? $json.body : ($json || {});
const url = payload.url;
if (!url) throw new Error('manual-fetch called without url');
const res = await helpers.httpRequest({
  method: 'GET',
  url,
  headers: { 'User-Agent': UA, Accept: 'application/pdf,*/*', 'Accept-Language': 'en-AU,en;q=0.9' },
  encoding: 'arraybuffer',
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  timeout: 90000,
});
if ([403, 429, 503].includes(res.statusCode)) throw new Error('fetch ' + res.statusCode + ' for ' + url + ' — possible block');
if (res.statusCode >= 400) return [{ json: { ok: false, url, error: 'http ' + res.statusCode } }];
const ct = String((res.headers && (res.headers['content-type'] || res.headers['Content-Type'])) || '').toLowerCase();
const buf = Buffer.isBuffer(res.body) ? res.body : Buffer.from(res.body);
const isPdf = ct.includes('pdf') || (buf.length > 4 && buf.slice(0, 5).toString('latin1') === '%PDF-');
if (!isPdf) {
  // Not a direct PDF — an HTML/portal/landing page. Flag for the browser path; return
  // a small snippet so the orchestrator (or Claude) can spot a direct PDF link inside.
  return [{ json: { ok: true, url, isPdf: false, contentType: ct, bytes: buf.length, note: 'not a direct PDF (portal/HTML) — route to the browser fetch path', htmlSnippet: buf.slice(0, 4000).toString('utf8') } }];
}
return [{ json: { ok: true, url, isPdf: true, contentType: ct, bytes: buf.length, base64: buf.toString('base64') } }];
